"""Dataset access. Datasets are plain JSON / JSONL files under ``datasets/`` (generated by ``tragedy.data.build``)."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[3]
DATASET_DIR = ROOT / "datasets"


@lru_cache(maxsize=64)
def _load(name: str) -> Any:
    jsonl = DATASET_DIR / f"{name}.jsonl"
    if jsonl.exists():
        return tuple(json.loads(line) for line in jsonl.read_text(encoding="utf-8").splitlines() if line.strip())
    return json.loads((DATASET_DIR / f"{name}.json").read_text(encoding="utf-8"))


def load(name: str) -> Any:
    """Return the dataset (list/dict for .json, tuple of dicts for .jsonl). Treat as read-only."""
    return _load(name)


def by_id(name: str, key: str = "id") -> dict[str, Any]:
    return {row[key]: row for row in load(name)}


def names() -> list[str]:
    return sorted(p.stem for p in DATASET_DIR.glob("*.json*") if p.stem != "MANIFEST")
